SELECT inventory.store_id, inventory.product_id, store_sales.product_id AS store_sale_product_id, store_sales.store_id AS store_sale_store_id, store_sales.revenue FROM inventory LEFT JOIN store_sales ON inventory.store_id = store_sales.store_id AND inventory.product_id = store_sales.product_id WHERE store_sales.revenue >= 1900 AND inventory.quantity BETWEEN 187 AND 228
